// Writes fonts.gen.ts: the faces in fonts/ as data URLs, which is how raea
// takes a font (it does not read one by path). Run before rendering:
//   bun run fonts.ts
import { readFileSync, writeFileSync } from "fs";
import { join } from "path";

const face = (file: string) => `data:font/ttf;base64,${readFileSync(join(import.meta.dir, "fonts", file)).toString("base64")}`;
writeFileSync(join(import.meta.dir, "fonts.gen.ts"), [
  "// Generated by fonts.ts: Michroma and IBM Plex Mono, both under the SIL Open Font License (fonts/OFL-*.txt).",
  `export const MICHROMA = "${face("Michroma-400.ttf")}";`,
  `export const PLEX_400 = "${face("PlexMono-400.ttf")}";`,
  `export const PLEX_500 = "${face("PlexMono-500.ttf")}";`,
  "",
].join("\n"));
